-- Phase 23D release, privacy, deployment and recovery governance. No production promotion is automatic.
CREATE TABLE public.brain_service_identities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), identity_code TEXT NOT NULL, secret_reference TEXT NOT NULL CHECK(secret_reference ~ '^(vault|kms|secret-manager|keychain|external):'), allowed_capabilities JSONB NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(allowed_capabilities)='array'), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','rotating','suspended','retired')), last_rotated_at TIMESTAMPTZ, rotation_due_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,environment,identity_code), UNIQUE(company_id,id));
CREATE TABLE public.brain_runtime_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), version_code TEXT NOT NULL, source_revision_metadata JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(source_revision_metadata)='object'), minimum_runtime_version TEXT, service_identity_reference TEXT CHECK(service_identity_reference IS NULL OR service_identity_reference ~ '^(vault|kms|secret-manager|keychain|external):'), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','under_review','approved_for_staging','staging','staging_verified','approved_for_production','production','suspended','rolled_back','retired')), owner_id UUID REFERENCES auth.users(id), reviewer_id UUID REFERENCES auth.users(id), approved_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,environment,version_code), UNIQUE(company_id,id));
CREATE TABLE public.brain_release_bundles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), bundle_code TEXT NOT NULL, version TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','under_review','approved_for_staging','staging','staging_verified','approved_for_production','production','suspended','rolled_back','retired')), owner_id UUID NOT NULL REFERENCES auth.users(id), reviewer_id UUID REFERENCES auth.users(id), approver_id UUID REFERENCES auth.users(id), release_notes TEXT NOT NULL, risk_classification TEXT NOT NULL CHECK(risk_classification IN ('low','medium','high','critical')), compatibility_checks JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(compatibility_checks)='object'), staging_verification JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(staging_verification)='object'), rollback_plan TEXT NOT NULL, rollback_target_id UUID, effective_at TIMESTAMPTZ, safety_evaluation_id UUID REFERENCES public.brain_safety_evaluations(id) ON DELETE SET NULL, benchmark_id UUID REFERENCES public.brain_benchmarks(id) ON DELETE SET NULL, promotion_candidate_id UUID REFERENCES public.brain_promotion_candidates(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,environment,bundle_code,version), UNIQUE(company_id,id));
CREATE TABLE public.brain_release_bundle_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL, release_bundle_id UUID NOT NULL, item_type TEXT NOT NULL CHECK(item_type IN ('dataset_contract_version','feature_version','rule_version','confidence_policy','query_definition','schedule','runtime_version','safety_evaluation','benchmark')), item_reference TEXT NOT NULL, version_reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,release_bundle_id,item_type,item_reference), FOREIGN KEY(company_id,release_bundle_id) REFERENCES public.brain_release_bundles(company_id,id) ON DELETE CASCADE);
ALTER TABLE public.brain_release_bundles ADD CONSTRAINT brain_release_rollback_target_fk FOREIGN KEY(company_id,rollback_target_id) REFERENCES public.brain_release_bundles(company_id,id) ON DELETE SET NULL;
CREATE TABLE public.brain_change_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), change_type TEXT NOT NULL CHECK(change_type IN ('rule_change','feature_change','dataset_change','schedule_change','runtime_change','policy_change','emergency_disable','recovery_replay','retention_policy')), scope TEXT NOT NULL, reason TEXT NOT NULL, risk_classification TEXT NOT NULL CHECK(risk_classification IN ('low','medium','high','critical')), requested_by UUID NOT NULL REFERENCES auth.users(id), reviewed_by UUID REFERENCES auth.users(id), approved_by UUID REFERENCES auth.users(id), planned_start_at TIMESTAMPTZ, planned_end_at TIMESTAMPTZ, implementation_status TEXT NOT NULL DEFAULT 'draft' CHECK(implementation_status IN ('draft','requested','under_review','approved','implemented','rolled_back','rejected')), validation_status TEXT NOT NULL DEFAULT 'unknown' CHECK(validation_status IN ('unknown','pending','passed','failed')), rollback_plan TEXT NOT NULL, incident_id UUID REFERENCES public.brain_incidents(id) ON DELETE SET NULL, release_bundle_id UUID, audit_metadata JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(audit_metadata)='object'), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(company_id,release_bundle_id) REFERENCES public.brain_release_bundles(company_id,id) ON DELETE SET NULL);
CREATE TABLE public.brain_retention_policies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, record_type TEXT NOT NULL CHECK(record_type IN ('event_consumptions','brain_jobs','brain_runs','feature_calculations','rule_evaluations','evidence','insights','recommendations','feedback','query_executions','logs','metrics','traces','evaluation_records','audit_records','incidents','release_records')), data_classification TEXT NOT NULL CHECK(data_classification IN ('public','internal','confidential','restricted','highly_restricted')), retention_days INTEGER NOT NULL CHECK(retention_days > 0), legal_requirement_metadata JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(legal_requirement_metadata)='object'), operational_need TEXT NOT NULL, audit_requirement BOOLEAN NOT NULL DEFAULT true, experimental BOOLEAN NOT NULL DEFAULT false, lifecycle_state TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle_state IN ('active','archived','purge_eligible','legal_hold','purged')), legal_hold BOOLEAN NOT NULL DEFAULT false, approved_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,record_type,data_classification,experimental));
CREATE TABLE public.brain_privacy_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), subject_type TEXT NOT NULL CHECK(subject_type IN ('dataset_contract','evaluation_dataset','release_bundle','schedule','query','export','incident')), subject_id UUID, purpose TEXT NOT NULL, data_classification TEXT NOT NULL CHECK(data_classification IN ('public','internal','confidential','restricted','highly_restricted')), status TEXT NOT NULL DEFAULT 'required' CHECK(status IN ('not_required','required','under_review','approved','rejected','expired')), reviewer_id UUID REFERENCES auth.users(id), reviewed_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, decision_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.brain_slo_definitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), slo_code TEXT NOT NULL, component TEXT NOT NULL, target_percent NUMERIC(5,2) NOT NULL CHECK(target_percent BETWEEN 0 AND 100), measurement_window_minutes INTEGER NOT NULL CHECK(measurement_window_minutes > 0), data_source TEXT NOT NULL, warning_threshold_percent NUMERIC(5,2) NOT NULL CHECK(warning_threshold_percent BETWEEN 0 AND 100), breach_threshold_percent NUMERIC(5,2) NOT NULL CHECK(breach_threshold_percent BETWEEN 0 AND 100), owner_id UUID REFERENCES auth.users(id), effective_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','suspended','retired')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,environment,slo_code));
CREATE TABLE public.brain_readiness_checks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), release_bundle_id UUID, check_code TEXT NOT NULL, required BOOLEAN NOT NULL DEFAULT true, state TEXT NOT NULL DEFAULT 'unknown' CHECK(state IN ('pass','warning','fail','unknown')), evidence_metadata JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(evidence_metadata)='object'), checked_at TIMESTAMPTZ, checked_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(company_id,release_bundle_id) REFERENCES public.brain_release_bundles(company_id,id) ON DELETE CASCADE, UNIQUE(company_id,environment,release_bundle_id,check_code));
CREATE TABLE public.brain_deployment_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, environment TEXT NOT NULL CHECK(environment IN ('local','development','test','staging','production')), runtime_version_id UUID, release_bundle_id UUID, status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','succeeded','failed','rolled_back','cancelled','unknown')), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, deployed_by UUID REFERENCES auth.users(id), approved_by UUID REFERENCES auth.users(id), source_revision_metadata JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(source_revision_metadata)='object'), migration_version TEXT, configuration_hash TEXT, health_check_result TEXT NOT NULL DEFAULT 'unknown' CHECK(health_check_result IN ('ready','ready_with_warnings','not_ready','unknown')), rollback_target_id UUID, failure_metadata JSONB NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(failure_metadata)='object'), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,id), FOREIGN KEY(company_id,runtime_version_id) REFERENCES public.brain_runtime_versions(company_id,id) ON DELETE SET NULL, FOREIGN KEY(company_id,release_bundle_id) REFERENCES public.brain_release_bundles(company_id,id) ON DELETE SET NULL, FOREIGN KEY(company_id,rollback_target_id) REFERENCES public.brain_deployment_records(company_id,id) ON DELETE SET NULL);
